        /**
         * Detail message.
         */msg: String
    )
    /**
     * Blind commitment failed.
     */
    case CommitmentFailed(
        /**
         * Detail message.
         */msg: String
    )
    /**
     * BBS+ credential parsing failed.
     */
    case CredentialParseFailed(
        /**
         * Detail message.
         */msg: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

